mapper.select:
SELECT COALESCE(sum( a.`total` ),0) `total`, COALESCE(sum( a.`duration` ),0) `duration`, COALESCE(sum( a.`flow` ),0) `flow` FROM `water_data_month` a where 1=1
and a.`data_time` between #{startTime} and #{endTime}
and a.`device_code` = #{deviceCode}

SELECT a.`data_time` `dataTime`, COALESCE(sum( a.`total` ),0) `total`, COALESCE(sum( a.`duration` ),0) `duration`, COALESCE(sum( a.`flow` ),0) `flow` FROM `water_data_month` a where 1=1
and a.`data_time` between #{startTime} and #{endTime}
and a.`device_code` = #{deviceCode}
